with filtered as (select id, product_name, category, brand, price, cost, stock_qty, launch_date, supplier_id, round(cost, 0) as cost_rounded from products where launch_date > date '2023-06-09' and supplier_id is not null and stock_qty = 249) select s.*, top1.order_item_quantity, top1.order_item_unit_price from filtered s join lateral (select c.quantity as order_item_quantity, c.unit_price as order_item_unit_price from order_items c where c.product_id = s.id order by c.unit_price desc, c.id desc limit 1) top1 on true
